void fg_impact_snapshot_destroy(fg_impact_snapshot *s) {
    if (!s)
        return;
    for (size_t i = 0; i < s->file_count; i++) {
        free(s->files[i].path);
        free(s->files[i].source);
    }
    for (size_t i = 0; i < s->symbol_count; i++) {
        free(s->symbols[i].name);
        free(s->symbols[i].kind);
    }
    free(s->files);
    free(s->symbols);
    free(s);
}
